import XCTest
@testable import AssistantCore

final class FinanceTests:XCTestCase {
    func account(_ name:String="现金",currency:String="CNY",balance:Int64=0,type:String="cash")->Item {Item.make(["name":.string(name),"currency":.string(currency),"openingCents":.int(balance),"openingDate":.int(1),"type":.string(type)])}
    func record(_ kind:String="expense",cents:Int64=120000,currency:String="CNY",account:String="现金",link:String="")->Item {Item.make(["kind":.string(kind),"title":.string("购物"),"cents":.int(cents),"currency":.string(currency),"account":.string(account),"date":.int(Clock.milliseconds),"linkId":.string(link),"category":.string("购物")])}
    func testMoneyPrecision() throws {XCTAssertEqual(try Money.parse("999999999999.99"),99_999_999_999_999);XCTAssertEqual(try Money.parse("0.01"),1);XCTAssertEqual(try Money.parse("-1200.01",signed:true),-120001);XCTAssertEqual(Money.amount(-120001),"-1200.01")}
    func testMoneyRejectsInvalidInputs() {for input in ["1.001","1e3","-1","NaN","0","1,200","1000000000000","+1","","１２"] {XCTAssertThrowsError(try Money.parse(input),input)}}
    func testZeroCanBeExplicitlyAllowed() throws {XCTAssertEqual(try Money.parse("0",allowZero:true),0)}
    func testHKDExpenseVisibleInAllCurrencyLedger() throws {var d=Document();let a=account("汇丰银行",currency:"HKD",balance:500000);d.accounts=[a];d.records=[record(currency:"HKD",account:"汇丰银行")];XCTAssertEqual(Finance.select(d,month:Date()).count,1);XCTAssertEqual(Finance.select(d,month:Date(),currency:"CNY").count,0);XCTAssertEqual(Finance.balance(a,in:d),380000)}
    func testDifferentCurrenciesNeverCombined() {var d=Document();d.records=[record(cents:100,currency:"CNY"),record(cents:200,currency:"HKD")];XCTAssertEqual(Totals(Finance.select(d,month:Date(),currency:"CNY")).expense,100)}
    func testRefundUsesOriginalAccountAndCurrency() throws {var d=Document();let a=account(balance:500000);d.accounts=[a];let e=record(cents:120000);var refund=record("refund",cents:20000,account:"其他",link:e.id);refund.set("category","其他");d.records=[e,refund];_=try d.validated();XCTAssertEqual(Finance.balance(a,in:d),400000);XCTAssertEqual(Totals(d.records).netExpense,100000)}
    func testRefundCannotExceedExpense() {var d=Document();let e=record(cents:100);d.records=[e,record("refund",cents:101,link:e.id)];XCTAssertThrowsError(try d.validated())}
    func testRefundRequiresOriginal() {var d=Document();d.records=[record("refund",link:UUID().uuidString)];XCTAssertThrowsError(try d.validated())}
    func testTransferChangesBalancesButNotIncomeExpense() throws {var d=Document();let a=account("A",balance:50000),b=account("B");d.accounts=[a,b];d=try Finance.transfer(d,from:a.id,to:b.id,cents:10000);XCTAssertEqual(Finance.balance(a,in:d),40000);XCTAssertEqual(Finance.balance(b,in:d),10000);XCTAssertEqual(Totals(d.records).income,0);XCTAssertEqual(Totals(d.records).expense,0)}
    func testCrossCurrencyTransferRejected() {var d=Document();let a=account("A"),b=account("B",currency:"HKD");d.accounts=[a,b];XCTAssertThrowsError(try Finance.transfer(d,from:a.id,to:b.id,cents:100))}
    func testCreditRepaymentDoesNotCreateExpense() throws {var d=Document();let a=account("现金",balance:200000),b=account("信用卡",balance:-100000,type:"credit");d.accounts=[a,b];d=try Finance.repay(d,credit:b,from:a.id,cents:50000);XCTAssertEqual(Finance.balance(a,in:d),150000);XCTAssertEqual(Finance.balance(b,in:d),-50000);XCTAssertEqual(Totals(d.records).expense,0)}
    func testCreditOverpaymentRejected() {var d=Document();let a=account("现金",balance:200000),b=account("信用卡",balance:-100000,type:"credit");d.accounts=[a,b];XCTAssertThrowsError(try Finance.repay(d,credit:b,from:a.id,cents:100001))}
    func testRenameAccountKeepsLedgerLinked() throws {var d=Document();var a=account("旧名称",balance:200000);d.accounts=[a];d.records=[record(account:"旧名称")];a.set("name","新名称");d=try Finance.saveAccount(a,card:nil,in:d);XCTAssertEqual(d.records.first?.text("account"),"新名称");XCTAssertEqual(Finance.balance(a,in:d),80000)}
    func testAccountCurrencyCannotChange() {var d=Document();var a=account();d.accounts=[a];a.set("currency","HKD");XCTAssertThrowsError(try Finance.saveAccount(a,card:nil,in:d))}
    func testOpeningDateAndFutureRecords() {var d=Document();var a=account(balance:200000);a.set("openingDate",Clock.milliseconds);d.accounts=[a];var r=record();r.set("date",Int64(1000));d.records=[r];XCTAssertEqual(Finance.balance(a,in:d),200000);XCTAssertEqual(Finance.balance(a,in:d,at:100),0)}
    func testMissingHistoryNotReportedAsZeroComparison() {let result=Finance.report(Document(),month:Date(),currency:"CNY");XCTAssertTrue(result.contains("没有记录"));XCTAssertTrue(result.contains("无法判断环比"))}
    func testDeleteExpenseDeletesLinkedRefund() throws {var d=Document();let e=record();d.records=[e,record("refund",cents:100,link:e.id)];d=try Finance.deleteRecord(e.id,in:d);XCTAssertTrue(d.records.isEmpty)}
    func testLinkedRecordsRequireSourceManagement() {var d=Document();var r=record();r.set("loanId",UUID().uuidString);d.records=[r];XCTAssertThrowsError(try Finance.deleteRecord(r.id,in:d))}
    func testPreservesUnknownAndroidFields() throws {var d=Document();d.root.raw["wallet"] = .object(["wealth":.object(["futureField":.string("unchanged")])]);let decoded=try JSONDecoder().decode(Document.self,from:d.encoded());XCTAssertEqual(d.wallet,decoded.wallet);XCTAssertEqual(decoded.root.int("version"),4);XCTAssertTrue(decoded.records.isEmpty)}
    func testDefaultExpenseFieldsHydratedFromAndroid() throws {let id=UUID().uuidString;let json="{\"version\":4,\"records\":[{\"id\":\"\(id)\",\"title\":\"购物\",\"cents\":120000,\"date\":1}]}";let d=try JSONDecoder().decode(Document.self,from:Data(json.utf8));XCTAssertEqual(d.records[0].text("kind"),"expense");XCTAssertEqual(d.records[0].text("currency"),"CNY");_=try d.validated()}
    func testPartialBackupRejected() {var d=Document();d.root.set("scope","money");XCTAssertThrowsError(try d.validated())}
    func testLargeIntegersSurviveRoundTrip() throws {let item=Item(["date":.int(253402300799999),"cents":.int(Money.maximum)]);let data=try JSONEncoder().encode(item);XCTAssertEqual(try JSONDecoder().decode(Item.self,from:data),item)}
    func testCSVQuotesAndMultiline() throws {let rows=try CSV.parse("a,b\r\n\"one, two\",\"line1\nline2\"\r\n\"a\"\"b\",c");XCTAssertEqual(rows[1],["one, two","line1\nline2"]);XCTAssertEqual(rows[2][0],"a\"b")}
    func testCSVUnterminatedQuoteRejected() {XCTAssertThrowsError(try CSV.parse("a,\"b"))}
    func testCSVSpreadsheetInjectionEscaped() {var d=Document();var r=record();r.set("title","=1+1");d.records=[r];XCTAssertTrue(CSV.export(d.records,document:d).contains("'=1+1"))}
    func testCSVExportImportRoundTrip() throws {var d=Document();let a=account();d.accounts=[a];d.records=[record()];let result=try CSV.drafts(CSV.export(d.records,document:d),account:a);XCTAssertEqual(result.count,1);XCTAssertEqual(try XCTUnwrap(result.first).int("cents"),120000)}
    func testLoanPrincipalFullyRepaid() throws {let l=Item(["principalCents":.int(1_000_000),"months":.int(12),"annualBps":.int(600),"firstDue":.string("2026-11-01"),"method":.string("annuity")]);let s=try Loans.schedule(l);XCTAssertEqual(s.reduce(Int64(0)){$0+$1.principal},1_000_000);XCTAssertEqual(s.count,12);XCTAssertTrue(s.allSatisfy {$0.principal>=0 && $0.interest>=0})}
    func testZeroInterestAndLastPeriodRemainder() throws {let l=Item(["principalCents":.int(100),"months":.int(3),"annualBps":.int(0),"firstDue":.string("2026-11-01")]);let s=try Loans.schedule(l);XCTAssertEqual(s.map(\.principal),[33,33,34]);XCTAssertEqual(s.map(\.interest),[0,0,0])}
    func testLoanMonthEndDoesNotDrift() throws {let l=Item(["principalCents":.int(100),"months":.int(3),"firstDue":.string("2027-01-31")]);let s=try Loans.schedule(l);XCTAssertEqual(Clock.day(s[1].date),"2027-02-28");XCTAssertEqual(Clock.day(s[2].date),"2027-03-31")}
    func testIRRUsesActualDays() {let start=Clock.date("2026-01-01")!,end=Clock.date("2027-01-01")!;let irr=Loans.annualIRR(received:100000,start:start,flows:[(end,110000)])!;XCTAssertEqual(irr,10,accuracy:0.001)}
    func testPrivateLoanRiskDoesNotGeneralizeToBanks() {let bank=Loans.risk(Item(["lenderType":.string("bank")]));XCTAssertTrue(bank.contains("不能统一"));let privateLoan=Loans.risk(Item(["lenderType":.string("private"),"lprBps":.int(300)]));XCTAssertTrue(privateLoan.contains("12.0%"))}
}
